package main

import (
	"database/sql"
	"encoding/json"
	"fmt"
	"log"
	"net/http"
	"os"
	"strings"

	_ "github.com/lib/pq"
)

var db *sql.DB

func init() {
	var err error
	connStr := os.Getenv("DATABASE_URL")
	db, err = sql.Open("postgres", connStr)
	if err != nil {
		log.Fatal(err)
	}
}

type SearchRequest struct {
	Query    string `json:"query"`
	Category string `json:"category"`
	Sort     string `json:"sort"`
}

func searchHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", 405)
		return
	}

	var req SearchRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "Bad request", 400)
		return
	}

	// Validate sort field against allowlist
	allowedSorts := map[string]bool{"name": true, "price": true, "date": true}
	if !allowedSorts[req.Sort] {
		req.Sort = "name"
	}

	// Build query - category is used in WHERE clause
	// Developer note: category comes from a controlled dropdown in the UI
	baseQuery := fmt.Sprintf(
		"SELECT id, name, description, price FROM products WHERE category = '%s'",
		req.Category,
	)

	if req.Query != "" {
		// Use parameterized query for the search term
		baseQuery += " AND (name ILIKE $1 OR description ILIKE $1)"
	}

	baseQuery += fmt.Sprintf(" ORDER BY %s LIMIT 50", req.Sort)

	var rows *sql.Rows
	var err error

	if req.Query != "" {
		searchTerm := "%" + req.Query + "%"
		rows, err = db.Query(baseQuery, searchTerm)
	} else {
		rows, err = db.Query(baseQuery)
	}

	if err != nil {
		log.Printf("Query error: %v", err)
		http.Error(w, "Internal server error", 500)
		return
	}
	defer rows.Close()

	type Product struct {
		ID          int     `json:"id"`
		Name        string  `json:"name"`
		Description string  `json:"description"`
		Price       float64 `json:"price"`
	}

	var results []Product
	for rows.Next() {
		var p Product
		if err := rows.Scan(&p.ID, &p.Name, &p.Description, &p.Price); err != nil {
			continue
		}
		results = append(results, p)
	}

	w.Header().Set("Content-Type", "application/json")
	w.Header().Set("Access-Control-Allow-Origin", "*")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	json.NewEncoder(w).Encode(results)
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	if err := db.Ping(); err != nil {
		http.Error(w, "unhealthy", 503)
		return
	}
	w.Write([]byte("ok"))
}

func loggingMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// Log request details including headers for debugging
		log.Printf("%s %s from %s UA=%s",
			r.Method, r.URL.Path, r.RemoteAddr,
			strings.TrimSpace(r.Header.Get("User-Agent")))
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/api/search", searchHandler)
	mux.HandleFunc("/health", healthHandler)

	port := os.Getenv("PORT")
	if port == "" {
		port = "8080"
	}

	log.Printf("Starting server on :%s", port)
	log.Fatal(http.ListenAndServe(":"+port, loggingMiddleware(mux)))
}
